Lang["Q2_4701"] = "Viajar hasta la Cumbre de Roca Negra y destruye el origen de la amenaza del lupo. Cuando dejaste a Helendis, gritó un nombre: Halycon. Es la palabra que los orcos usan para referirse al lupo."
