Lang["Q2_6081"] = "Speak with Ormak Grimshot in Orgrimmar."
Lang["Q2_6082"] = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill."
Lang["Q2_6083"] = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill."
Lang["Q2_6084"] = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos."
Lang["Q2_6085"] = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
Lang["Q2_6086"] = "Speak with Belia Thundergranite in Ironforge."
Lang["Q2_6087"] = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6088"] = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6089"] = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."
Lang["Q2_6101"] = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6102"] = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6103"] = "Speak to Jocaste in the Cenarion Enclave, in Darnassus."
Lang["Q2_6121"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6122"] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."
Lang["Q2_6123"] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."
Lang["Q2_6124"] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."
Lang["Q2_6125"] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_6126"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6127"] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."
Lang["Q2_6128"] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."
Lang["Q2_6129"] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."
Lang["Q2_6130"] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff."
Lang["Q2_6133"] = "Viaja a la frontera norte de las Tierras de la Peste del Este y recupera el Registro de Quel'Thalas. Se encuentra en algún lugar del Refugio Quel'Lithien. También tienes que matar a 8 exploradores, 8 zancaminos y 8 Leñantros."
Lang["Q2_6135"] = "Encuentra a Alatardecer y mátalo. Recoge un parche de piel de Alatardecer de su cadáver y llévaselo a Nathanos Clamorinfecto.Se dice que Alatardecer vaga por el campo, al norte de la Hacienda de Marris."
Lang["Q2_6136"] = "Encuentra a Borelgore en las planicies del norte de las Tierras de la Peste del Este y destrúyelo. Vuelve junto a Nathanos Clamorinfecto cuando hayas cumplido la misión."
Lang["Q2_6141"] = "Habla con el hermano Antón en Desolace."
Lang["Q2_6144"] = "Viaja a Entrañas y habla con Varimathras."
Lang["Q2_6163"] = "Viaja a Stratholme y mata a Ramstein el Empachador. Coge su cabeza y llévasela como souvenir a Nathanos."
Lang["Q2_63"] = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."
Lang["Q2_65"] = "Gryan Mantorrecio quiere que hables con Wiley en Villa del Lago."
Lang["Q2_6521"] = "Lleva la cabeza del embajador Malcin a Varimathras, que está en Entrañas."
Lang["Q2_6522"] = "Lleva el pergamino a Varimathras, que está en Entrañas."
Lang["Q2_65593"] = "Llévale los corazones de Avelina Lilly e Isaac Pearson a Carendin Halgar, que está en el Templo de los Condenados."
Lang["Q2_65597"] = "Utilizando los corazones de los amantes, invoca y domina a un íncubo, y después devuélvele los corazones de amantes a Carendin Halgar, que está en el Barrio de la Magia de Entrañas."
Lang["Q2_65601"] = "Speak with Magar in Orgrimmar."
Lang["Q2_65602"] = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."
Lang["Q2_65603"] = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb."
Lang["Q2_65604"] = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar."
Lang["Q2_6561"] = "Llévale la cabeza del Señor Crepuscular Kelris a Bashana Runatótem en Cima del Trueno."
Lang["Q2_65610"] = "Investiga el Lago Cielo Estrellado de Vallefresno e informa de tus hallazgos a Gan'rul Ojosangre, que está en Orgrimmar."
Lang["Q2_6562"] = "Habla con Je'neu Sancrea en Vallefresno."
Lang["Q2_6563"] = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno."
Lang["Q2_6564"] = "Llévale la nota humedecida a Je'neu Sancrea en Vallefresno."
Lang["Q2_6565"] = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve junto a Je'neu Sancrea en Vallefresno."
Lang["Q2_6626"] = "Mata a 8 guardias de batalla y 8 tejespinas Rajacieno y 8 adeptos Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno."
Lang["Q2_6627"] = "Responde la pregunta de Braug Espiritoscuro con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés <listo/lista>."
