Lang["Q2_7494"] = "Habla con Latronicus Lanzaluna en el Bastión Plumaluna de Feralas."
Lang["Q2_7499"] = "Return the book to its rightful owners."
Lang["Q2_7506"] = "Return the book to its rightful owners."
Lang["Q2_7562"] = "Habla con Mor'zul Sangredoble en Las Estepas Ardientes."
Lang["Q2_7563"] = "Llévale 30 botellas de sangre de bestia embravecida a Mor'zul Sangredoble en Las Estepas Ardientes."
Lang["Q2_7564"] = "Llévale el estuche de sangre a Gorzeeki Ojosalvajes en Las Estepas Ardientes."
Lang["Q2_7581"] = "Viaja a La Masacre en Feralas y consigue 15 muestras de sangre de sátiro del sátiro Mala Hierba que habita en el Barrio Alabeo. Cuando hayas acabado, ve a ver a Daio a la Escara Impía."
Lang["Q2_7582"] = "Viaja a la Garganta Negro Rumor en Cuna del Invierno y recoge 5 Lágrimas de los Hederine de los demonios Hederine que ocupan la garganta. Cuando hayas cumplido tu tarea, ve a ver a Daio a la Escara Impía."
Lang["Q2_7583"] = "Aventúrate en la Escara Impía y localiza a un comandante Guardia apocalíptico.\n\nUtiliza la prisión de cristal resplandeciente para atrapar al comandante Guardia apocalíptico. Prepárate para una sucesión de ataques pues el demonio intentará escapar.\n\nSi tienes éxito, llévale el Guardia apocalíptico encarcelado a Daio, que está en la Escara Impía."
Lang["Q2_7601"] = "Habla con Diblis en Frondavil."
Lang["Q2_7602"] = "Diblis de Frondavil te ha pedido que le lleves 3 esencias inferi puras que provengan de 3 lugares distintos.\n\nLos sátiros Legashi de Azshara tienen la esencia inferi pura de su región. Los legionarios Jaedenar de Jaedenar tienen la esencia inferi pura de su región. Los guardias malditos de Las Tierras Devastadas tienen la esencia inferi pura de su región.\n\nReúne las esencias inferi puras y vuelve con Diblis a Frondavil."
Lang["Q2_7603"] = "Busca los restos de Kroshius en la Cañada Gran Cicatriz de Frondavil. Cuando localices sus restos, utiliza el fuego inferi cerca de ellos y espera el regreso de Kroshius. Cuando el inferno se haya despertado, acaba con él y extrae de su cuerpo el núcleo infernal de Kroshius.\n\nLleva el núcleo infernal de Kroshius a Niby el Todopoderoso a Frondavil."
Lang["Q2_7621"] = "A Warning"
Lang["Q2_7622"] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain."
Lang["Q2_7623"] = "Cómprale oscuras pociones a Gorzeeki en Las Estepas Ardientes.\n\nUsa la pociones para viajar por Jaedenar y habla con Lord Pesadilla."
Lang["Q2_7624"] = "Enfréntate a Ulathek y llévale el corazón del traidor a Lord Pesadilla en Jaedenar."
Lang["Q2_7625"] = "Cómprale polvo estelar xorotiano a Ur'dan. Llévaselo a Gorzeeki Ojosalvajes en Las Estepas Ardientes."
Lang["Q2_7626"] = "Llévale 10 elixires de poder de las sombras a Gorzeeki Ojosalvajes en Las Estepas Ardientes."
Lang["Q2_7627"] = "Llévale 6 grandes fragmentos brillantes y 25 minerales de hierro negro a Gorzeeki Ojosalvajes en Las Estepas Ardientes."
Lang["Q2_7628"] = "Lleva 35 escamas de dragón negro a Gorzeeki Ojosalvajes a Las Estepas Ardientes."
Lang["Q2_7629"] = "Llévale el diablillo en un tarro al laboratorio de alquimia de Scholomance. Después de crear el pergamino llévale el tarro a Gorzeeki Ojosalvajes."
Lang["Q2_7630"] = "Lleva 3 lingotes de arcanita a Gorzeeki Ojosalvajes a Las Estepas Ardientes."
Lang["Q2_7631"] = "Lee las instrucciones de Mor'zul. Invoca al Corcel de la Muerte Xorothiano, derrótalo y después vincula su espíritu al tuyo."
Lang["Q2_7632"] = "Find the owner of the Ancient Petrified Leaf. Good luck, you; It's a big world."
Lang["Q2_7633"] = "An Introduction"
Lang["Q2_7634"] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."
Lang["Q2_7635"] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."
Lang["Q2_7636"] = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself."
Lang["Q2_7637"] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."
Lang["Q2_7638"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_7639"] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7640"] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7641"] = "Speak with Grimand Elmore in Stormwind's Dwarven District."
Lang["Q2_7642"] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."
Lang["Q2_7643"] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."
Lang["Q2_7644"] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7645"] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities."
Lang["Q2_7646"] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7647"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."
Lang["Q2_7648"] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."
Lang["Q2_7666"] = "Again Into the Great Ossuary"
Lang["Q2_7667"] = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."
Lang["Q2_7668"] = "The Darkreaver Menace"
Lang["Q2_7669"] = "Again Into the Great Ossuary"
Lang["Q2_7670"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_78916"] = "Lleva la Perla de Brazanegra al vigía del alba Selgorm en Darnassus."
Lang["Q2_78917"] = "Lleva la Perla de Brazanegra a Bashana Tótem de Runa en Cima del Trueno."
Lang["Q2_79007"] = "Viaja a 46, 73 en Los Baldíos. Interactúa con los Restos calcinados y acepta la misión.\n\nEntrégala en 37, 50 en los Páramos de Poniente interactuando con el Tablón clavado. Acepta Peldaños en ese tablón antes de irte."
Lang["Q2_79008"] = "Viaja a 37, 50 en los Páramos de Poniente. Interactúa con los Restos calcinados junto al Tablón clavado y acepta la misión.\n\nEntrégala en 46, 73 en Los Baldíos, en los Restos calcinados, luego interactúa allí con el Tablón clavado y acepta Peldaños."
Lang["Q2_79192"] = "La Horda acepta esto en el Tablón clavado de 37, 50 en los Páramos de Poniente. La Alianza lo acepta en el Tablón clavado de 46, 73 en Los Baldíos.\n\nViaja a 51, 51 en la Sierra Espolón. Desde el camino, sigue la abertura hacia las montañas y el sendero hasta el campamento. Interactúa con los Restos de bolsillo (40.8, 52.5)."
Lang["Q2_79974"] = "Interactúa con el Montículo de tierra en la Sierra Espolón (39.6, 49.9) para aceptar esta misión.\n\nViaja a la presa en 49, 12 en Loch Modan. Salta hasta el saliente e interactúa con la Figurilla tallada (49.5, 12.8)."
Lang["Q2_79975"] = "Interactúa con la Figurilla tallada en la presa de Loch Modan (49.5, 12.8) para aceptar esta misión.\n\nViaja a 81, 56 en las Laderas de Trabalomas. De cara a la puerta hacia las Tierras Altas de Arathi, gira a la izquierda y sigue el muro hasta el carro caído. Sigue el recorrido de saltos hacia el campamento e interactúa con la Bolsa de mensajero (Tierras Altas de Arathi 22.4, 24.2)."
Lang["Q2_79976"] = "Interactúa con la Bolsa de mensajero y después con la Bolsa enrollada a toda prisa que hay justo debajo para recibir el Saco de dormir acogedor."
Lang["Q2_79980"] = "En el campamento de la Sierra Espolón, interactúa con los Restos de bolsillo (40.8, 52.5) para aceptar esta misión.\n\nCruza el campamento y salta montaña abajo hasta el saliente con el Montículo de tierra (39.6, 49.9), luego interactúa con él."
Lang["Q2_79987"] = "Puedes quedarte el anillo, o encontrar a la persona responsable de la impronta y los grabados del interior."
Lang["Q2_80140"] = "Puedes quedarte el anillo, o encontrar a la persona responsable de la impronta y los grabados del interior."
