Lang["Q2_92753"] = "Encuentra la forja oculta en las Minas de la Muerte y coloca cerca los explosivos superdestructivos. Después, reúnete con Alba Fairmoon a la salida de las Minas de la Muerte."
Lang["Q2_92819"] = "Use the detonator."
Lang["Q2_9362"] = "Recupera la concha centelleante para el archimago Xylem. El archimago vive en una torre en lo alto del precipicio de Azshara."
Lang["Q2_9364"] = "Aplica el hechizo polimórfico a las sirenas Látigo de Ira de Azshara y mata a los clones que aparezcan pasados unos segundos. Cuando hayas matado a 50, vuelve junto al archimago Xylem en Azshara."
